const token = $input.first().json.access_token;
if (!token) throw new Error('No se obtuvo access_token: ' + JSON.stringify($input.first().json));

const orgId = $env.ZOHO_ORG_ID;
const since = new Date(Date.now() - 25 * 60 * 60 * 1000).toISOString();

return [{ json: { token, orgId, since } }];

const token  = $input.first().json.token;
const orgId  = $input.first().json.orgId;
const since  = $input.first().json.since;

const allTickets = [];
let from = 1;
const limit = 50;

while (true) {
  const url = `https://desk.zoho.com/api/v1/tickets?from=${from}&limit=${limit}&sortBy=modifiedTime&order=desc`;
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: {
      'Authorization': `Zoho-oauthtoken ${token}`,
      'orgId': orgId,
    },
  });

  const rows = res.data || [];
  if (!rows.length) break;

  // Filtrar solo los modificados en las últimas 25h
  const recent = rows.filter(t => t.modifiedTime && t.modifiedTime >= since);
  allTickets.push(...recent);

  // Si el último ticket de la página ya es más antiguo que el rango, parar
  const last = rows.at(-1);
  if (!last?.modifiedTime || last.modifiedTime < since) break;
  if (rows.length < limit) break;

  from += limit;
  // Evitar rate limit
  await new Promise(r => setTimeout(r, 200));
}

if (!allTickets.length) return [{ json: { msg: 'Sin tickets nuevos', count: 0 } }];

// Mapear a estructura de la tabla zoho_tickets
const records = allTickets.map(t => ({
  id:                 t.id,
  ticket_number:      t.ticketNumber || null,
  subject:            t.subject || null,
  status:             t.status || null,
  priority:           t.priority || null,
  channel:            t.channel || null,
  department_id:      t.departmentId || null,
  contact_id:         t.contactId || null,
  assignee_id:        t.assigneeId || null,
  created_time:       t.createdTime || null,
  modified_time:      t.modifiedTime || null,
  closed_time:        t.closedTime || null,
  first_response_time: t.firstResponseTime ? parseInt(t.firstResponseTime) : null,
  raw_data:           t,
  synced_at:          new Date().toISOString(),
}));

return records.map(r => ({ json: r }));
